"use client";
import { RiUserSearchLine, RiTeamLine, RiTimeLine, RiUserMinusLine } from "@remixicon/react";
import {
  RiFilePaper2Line,
  RiPhoneLine,
  RiChatSmile2Line,
  RiShakeHandsLine,
  RiUserAddLine,
} from "@remixicon/react";
import { BarListCard } from "../charts/bar-list-card";
import { ComboChartCard } from "../charts/combo-chart-card";
import { RadarChartCard } from "../charts/radar-chart-card";
import { StageBarsCard } from "../charts/stage-bars-card";
import { StatCards } from "../dashboard/stat-cards";
import { type DashboardTemplateProps, DataDashboard } from "./data-dashboard";
import { HR_HIRING_RANGES, HR_PIPELINE_RANGES, HR_ENGAGEMENT_RANGES } from "./hr-chart-data";
import { RecentHiresCard, type RecentHire } from "./recent-hires-card";

export interface HRManagementProps extends DashboardTemplateProps {
  hires?: RecentHire[];
  hiringSourceLabel?: string;
}
export function HRManagement({
  hires,
  hiringSourceLabel = "Professional network",
  ...props
}: HRManagementProps = {}) {
  return (
    <DataDashboard
      icon={RiTeamLine}
      tableLayout="fluid"
      enableRecordCreation={false}
      {...props}
      kind="hr"
      title="HR Team"
      selected="hr"
      action="Add employee"
    >
      <StatCards
        stats={[
          {
            icon: RiTeamLine,
            label: "Employees",
            value: "248",
            delta: "+4.2%",
            deltaColor: "lime",
          },
          {
            icon: RiUserSearchLine,
            label: "Open roles",
            value: "12",
            delta: "+8.3%",
            deltaColor: "neutral",
          },
          {
            icon: RiTimeLine,
            label: "Time to hire",
            value: "24 days",
            delta: "-8.3%",
            deltaColor: "lime",
          },
          {
            icon: RiUserMinusLine,
            label: "Attrition",
            value: "3.8%",
            delta: "-0.6%",
            deltaColor: "lime",
          },
        ]}
      />
      <div className="grid items-start gap-4 md:grid-cols-2 xl:grid-cols-3">
        <RecentHiresCard hires={hires} team={props.team?.name} />
        <StageBarsCard
          title="Hiring pipeline"
          ranges={HR_PIPELINE_RANGES.map((range) => ({
            ...range,
            stages: range.stages.map((stage, i) => {
              const Icon = [
                RiFilePaper2Line,
                RiPhoneLine,
                RiChatSmile2Line,
                RiShakeHandsLine,
                RiUserAddLine,
              ][i]!;
              return { ...stage, icon: <Icon className="size-3.5 shrink-0 text-neutral-950" /> };
            }),
          }))}
          range="Last 30 days"
          delta={0.062}
        />
        <RadarChartCard
          className="md:col-span-2 xl:col-span-1"
          title="Team engagement"
          variant="score"
          range="Q3 survey"
          max={100}
          alertBelow={60}
          ranges={HR_ENGAGEMENT_RANGES}
          series={[{ key: "score", label: "Engagement" }]}
        />
      </div>
      <div className="grid items-stretch gap-4 xl:grid-cols-2">
        <ComboChartCard
          title="Hires"
          ranges={HR_HIRING_RANGES}
          bar={{ key: "hires", label: "Hires" }}
          line={{
            key: "attrition",
            label: "Attrition",
            color: "var(--color-chart-3)",
            activeColor: "var(--color-chart-3-active)",
            format: (n) => `${+n.toFixed(1)}%`,
          }}
          range="This year"
          delta={0.084}
        />
        <BarListCard
          metric="value"
          metricLabel="People"
          tabs={[
            {
              id: "departments",
              label: "Departments",
              items: [
                { label: "Engineering", value: 96 },
                { label: "Sales", value: 44 },
                { label: "Support", value: 38 },
                { label: "Marketing", value: 26 },
                { label: "Design", value: 22 },
                { label: "Operations", value: 14 },
                { label: "People", value: 8 },
              ],
            },
            {
              id: "sources",
              label: "Hiring sources",
              items: [
                { label: "Referrals", value: 52 },
                { label: hiringSourceLabel, value: 38 },
                { label: "Job boards", value: 24 },
                { label: "Inbound", value: 17 },
                { label: "Agencies", value: 10 },
              ],
            },
            {
              id: "locations",
              label: "Locations",
              items: [
                { label: "Remote", value: 84 },
                { label: "Berlin", value: 62 },
                { label: "London", value: 48 },
                { label: "New York", value: 34 },
                { label: "Singapore", value: 20 },
              ],
            },
          ]}
        />
      </div>
    </DataDashboard>
  );
}
